(()=>{
 const $=id=>document.getElementById(id),D=CloseReadData;let pending=null,deleting=null,working=false;
 const node=(tag,text,parent)=>{const el=document.createElement(tag);el.textContent=text;parent.append(el);return el;};
 async function run(fn){if(working)return;working=true;document.querySelectorAll('button,input').forEach(b=>b.disabled=true);try{await fn();}catch(e){$('status').textContent='操作未全部完成：'+e.message+' 请刷新核对后再决定，不会自动重试。';}finally{working=false;document.querySelectorAll('button,input').forEach(b=>b.disabled=false);}}
 async function list(){const {items}=await D.request('trash');$('trash').replaceChildren();if(!items.length)node('p','回收站是空的。',$('trash'));for(const r of items){const row=node('article','',$('trash'));row.className='row';node('h3',r.lesson.title,row);node('p',r.language+' · '+new Date(r.deletedAt).toLocaleDateString('en-US'),row).className='muted';const restore=node('button','恢复文章',row);restore.onclick=()=>run(async()=>{await D.article(r.id,'restore');await list();$('status').textContent='已恢复，可回文章库继续阅读。';});const purge=node('button','永久删除…',row);purge.onclick=()=>{deleting=r.id;$('delete-title').textContent=r.lesson.title;$('confirm').showModal();};}}
 $('keep').onclick=()=>$('confirm').close();$('purge').onclick=()=>run(async()=>{await D.article(deleting,'purge');$('confirm').close();await list();$('status').textContent='已永久删除文章及其程序缓存、本浏览器笔记与生词；不能从回收站恢复。原始文件未改动。';});
 $('refresh').onclick=()=>run(list);
 $('backup').onclick=()=>run(async()=>{const backup=await D.request('backup');backup.browser=D.snapshot();D.download(backup);$('status').textContent='已发起备份下载，请确认文件已保存。';});
 $('file').onchange=()=>run(async()=>{pending=null;$('restore').hidden=true;$('preview').textContent='';const file=$('file').files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('备份不能超过 50 MB');const b=JSON.parse(await file.text());if(b.format!=='closeread-backup'||b.version!==1||!Array.isArray(b.articles)||!Array.isArray(b.trash))throw Error('请选择本页导出的完整备份');D.validateBrowser(b.browser);pending=b;$('preview').textContent=`备份含 ${b.articles.length} 篇文章、${b.trash.length} 篇回收站文章、${Object.keys(b.browser).length} 组浏览器数据。将补回缺失项，跳过同编号文章和已有浏览器数据。`;$('restore').hidden=false;});
 $('restore').onclick=()=>run(async()=>{if(!pending)return;D.validateBrowser(pending.browser);const result=await D.request('import',pending);let count=0,skipped=0;for(const [k,v] of Object.entries(pending.browser)){if(localStorage.getItem(k)!==null){skipped++;continue;}localStorage.setItem(k,v);count++;}pending=null;$('restore').hidden=true;$('preview').textContent='';await list();$('status').textContent=`已补回 ${result.restored} 篇文章、${count} 组浏览器数据；跳过已有的 ${result.skipped} 篇文章、${skipped} 组浏览器数据。请重新打开其他学习页面。`;});
 run(list);
})();
